INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl001', 'NPL-001', 'bpc-157', 'BPC-157', 'glycyl-L-alpha-glutamyl-L-prolyl-L-prolyl-L-prolylglycyl-L-lysyl-L-prolyl-L-alanyl-L-alpha-aspartyl-L-alpha-aspartyl-L-alanylglycyl-L-leucyl-L-valine', '["Body Protection Compound-157","PL 14736","Pentadecapeptide BPC 157"]', 'Peptides', '137525-51-0', '[{"form":"Acetate salt","cas":"1628202-19-6"},{"form":"Acetate salt (alternate registry)","cas":"216441-37-1"}]', 'GEPPPGKPADDAGLV', 'Gly-Glu-Pro-Pro-Pro-Gly-Lys-Pro-Ala-Asp-Asp-Ala-Gly-Leu-Val', 'C62H98N16O22', '1419.5 g/mol', NULL, NULL, 'HEEWEZGQMLZMFE-RKGINYAYSA-N', '9941957', 'Greater than or equal to 95% by HPLC', 'Solid', 'Supplied as the acetate salt (C64H102N16O24, 1479.6 g/mol) unless otherwise stated on the lot certificate', '[]', 'Minus 20 C', 'Prepare fresh; store aliquots at minus 20 C and avoid repeated freeze-thaw', 'At least 4 years when stored as supplied at minus 20 C', 'Ambient', 'available', 'A synthetic pentadecapeptide of sequence GEPPPGKPADDAGLV. Supplied lyophilised as the acetate salt. Identity is confirmed by mass spectrometry and purity determined by reversed-phase HPLC against the lot certificate. No USP or NF monograph exists for this substance.', '["CAS, formula, molecular weight, sequence and InChI Key verified against PubChem CID 9941957 and EPA CompTox.","Acetate salt data (C64H102N16O24, 1479.6 g/mol) from PubChem CID 155977614.","Purity specification, storage, stability and ambient shipping per Cayman Chemical catalog 30989.","Suppliers disagree on shipping condition: Cayman lists ambient, MilliporeSigma SML1719 lists wet ice. Confirm against the supplying lot.","Physical form is published only as \"a solid\" (Cayman) and \"film, colorless\" (Sigma). Not described here as a white lyophilised powder, which is unsourced.","Cayman publishes no solubility data for this compound. The solubility list is deliberately empty rather than estimated."]', 1, '/products/bpc-157.png', 1, 'published', NULL, 10, 'seed');
