INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl002', 'NPL-002', 'nad', 'beta-NAD+', 'beta-Nicotinamide adenine dinucleotide, oxidised form', '["NAD+","beta-NAD","Nicotinamide adenine dinucleotide","Coenzyme I","DPN"]', 'Nucleotides & cofactors', '53-84-9', '[{"form":"Monosodium salt","cas":"20111-18-6"}]', NULL, NULL, 'C21H27N7O14P2', '663.43 g/mol', NULL, NULL, NULL, '5892', 'Greater than or equal to 95% by HPLC', 'Solid', 'Free acid. Hydrate forms are supplied under the same registry number', '[{"solvent":"PBS (pH 7.2)","concentration":"10 mg/mL","source":"Cayman Chemical 16077"},{"solvent":"PBS (pH 7.2)","concentration":"100 mg/mL","note":"with sonication and warming to 60 C","source":"MedChemExpress HY-B0445"}]', 'Minus 20 C, protected from moisture', 'Prepare fresh in aqueous buffer; do not store aqueous stocks long term', 'Hygroscopic. Hydrolyses in aqueous solution; stability is pH and temperature dependent', 'Not published by suppliers - confirm at order', 'available', 'The oxidised form of nicotinamide adenine dinucleotide, a pyridine nucleotide cofactor used as a substrate and redox couple in enzymatic assay work. Supplied as the free acid. beta-NAD appears in the USP-NF Reagents section as a reagent specification; it has no drug substance monograph.', '["Use PubChem CID 5892. CID 925 is the stereo-undefined record and carries no CAS.","CAS, formula and molecular weight verified against PubChem and EPA CompTox.","Suppliers disagree on solubility: Cayman 16077 publishes 10 mg/mL in PBS; MedChemExpress HY-B0445 publishes 100 mg/mL with sonication and heating. Both are shown rather than reconciled.","Suppliers disagree on hazard classification: MilliporeSigma N8285 states not a hazardous substance or mixture; Cayman 16077 assigns GHS07 Warning with H315, H319 and H335. The SDS issued with the supplied lot governs.","CAS 606-68-8 appears in searches for NAD disodium but is NADH disodium, the reduced form. Not used here.","USP-NF reagent entry USPNF_R2223_01_01. A reagent specification, not a monograph."]', 1, NULL, 1, 'published', NULL, 20, 'seed');
