INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl003', 'NPL-003', 'ghk', 'GHK', 'glycyl-L-histidyl-L-lysine', '["Gly-His-Lys","Tripeptide-1"]', 'Peptides', '49557-75-7', '[{"form":"Acetate salt","cas":"72957-37-0"}]', 'GHK', 'Gly-His-Lys', 'C14H24N6O4', '340.38 g/mol', NULL, NULL, NULL, '73587', 'Greater than or equal to 95% by HPLC', 'Solid', 'Free peptide. Acetate salt (400.43 g/mol) supplied under CAS 72957-37-0', '[]', 'Minus 20 C', 'Prepare fresh; store aliquots at minus 20 C', 'Refer to the lot certificate', 'Ambient', 'available', 'A tripeptide of sequence Gly-His-Lys. Supplied as the free peptide; the acetate salt is available under a separate registry number. Identity confirmed by mass spectrometry, purity by reversed-phase HPLC. Distinct from the copper(II) complex, listed separately as NPL-004.', '["CAS 49557-75-7, formula and molecular weight verified against PubChem CID 73587.","Acetate salt CAS 72957-37-0 confirmed via MilliporeSigma G1887 (400.43 g/mol).","Cayman catalog 27168. MedChemExpress HY-P0063 is the copper complex, not this item.","Solubility in ethanol and DMF is unpublished by all suppliers checked. The list is left empty rather than estimated."]', 1, NULL, 0, 'published', NULL, 30, 'seed');
