INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl009', 'NPL-009', 'tb-500', 'TB-500', 'N-acetyl-L-leucyl-L-lysyl-L-lysyl-L-threonyl-L-alpha-glutamyl-L-threonyl-L-glutamine', '["Ac-LKKTETQ","N-acetyl thymosin beta-4 (17-23)"]', 'Peptides', '885340-08-9', '[]', 'LKKTETQ', 'Ac-Leu-Lys-Lys-Thr-Glu-Thr-Gln', 'C38H68N10O14', '889.0 g/mol', NULL, NULL, NULL, NULL, 'Greater than or equal to 98% by HPLC', 'Solid', 'Supplied as the acetate salt unless otherwise stated on the lot certificate', '[]', 'Minus 20 C', 'Prepare fresh; store aliquots at minus 20 C', 'Refer to the lot certificate', 'Ambient', 'enquire', 'A synthetic N-acetylated heptapeptide of sequence LKKTETQ, corresponding to residues 17 to 23 of thymosin beta-4. It is not the full-length 43-residue protein, which is a different substance under a different registry number. Supplied lyophilised. Identity confirmed by mass spectrometry, purity determined by reversed-phase HPLC against the lot certificate.', '["CAS 885340-08-9, formula C38H68N10O14 and molecular weight 889.02 g/mol per ChemicalBook CB34713831, checked 19 Sep 2026. No PubChem CID located for the acetylated fragment.","Full-length thymosin beta-4 is CAS 77591-33-4 and is not this item. Suppliers sell both under the name TB-500; the lot certificate must state which substance was supplied.","Salt form is not published consistently by suppliers; the lot certificate governs."]', 0, NULL, 0, 'published', NULL, 90, 'seed');
