INSERT OR IGNORE INTO products (id, code, slug, name, formal_name, synonyms, chemical_class, cas_number, related_cas, sequence_one_letter, sequence_three_letter, molecular_formula, molecular_weight, exact_mass, smiles, inchi_key, pubchem_cid, purity, form, salt_form, solubility, storage_solid, storage_stock, stability, shipping, status, description, source_notes, has_sds, image, featured, visibility, withdrawn_reason, sort_order, updated_by) VALUES ('prd_npl011', 'NPL-011', 'aod-9604', 'AOD-9604', 'L-tyrosyl-L-leucyl-L-arginyl-L-isoleucyl-L-valyl-L-glutaminyl-L-cysteinyl-L-arginyl-L-seryl-L-valyl-L-alpha-glutamylglycyl-L-seryl-L-cysteinylglycyl-L-phenylalanine, cyclic (7-14)-disulfide', '["Tyr-hGH (177-191)","AOD 9604"]', 'Peptides', '221231-10-3', '[]', 'YLRIVQCRSVEGSCGF', 'Tyr-Leu-Arg-Ile-Val-Gln-Cys-Arg-Ser-Val-Glu-Gly-Ser-Cys-Gly-Phe (disulfide Cys7-Cys14)', 'C78H123N23O23S2', '1815.1 g/mol', NULL, NULL, NULL, '71300630', 'Greater than or equal to 98% by HPLC', 'Solid', 'Supplied as the acetate salt unless otherwise stated on the lot certificate', '[]', 'Minus 20 C', 'Prepare fresh; store aliquots at minus 20 C', 'Refer to the lot certificate', 'Ambient', 'enquire', 'A synthetic 16-residue peptide corresponding to residues 177 to 191 of the 191-residue human somatotropin sequence with an added N-terminal tyrosine, containing one intramolecular disulfide. Supplied lyophilised. Identity confirmed by mass spectrometry, purity determined by reversed-phase HPLC against the lot certificate.', '["CAS 221231-10-3, formula C78H123N23O23S2 and molecular weight 1815.1 g/mol verified against PubChem CID 71300630 on 19 Sep 2026.","Formal name written from the published residue sequence and disulfide position; confirm against the supplier certificate before the first lot is released."]', 0, NULL, 0, 'published', NULL, 110, 'seed');
